import{_ as e,o as s,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Espacio de Trabajo","description":"","frontmatter":{},"headers":[],"relativePath":"es/concepts/workspace.md","filePath":"es/concepts/workspace.md","lastUpdated":1784904021000}'),t={name:"es/concepts/workspace.md"};function o(c,a,p,l,d,r){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="espacio-de-trabajo" tabindex="-1">Espacio de Trabajo <a class="header-anchor" href="#espacio-de-trabajo" aria-label="Permalink to &quot;Espacio de Trabajo&quot;">​</a></h1><p>El espacio de trabajo es el directorio donde swag2mcp almacena todos sus datos — configuración, especificaciones en caché, archivos de especificación locales, respuestas guardadas y scripts de autenticación.</p><h2 id="estructura" tabindex="-1">Estructura <a class="header-anchor" href="#estructura" aria-label="Permalink to &quot;Estructura&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/                          # Raíz del espacio de trabajo (predeterminado)</span></span>
<span class="line"><span>├── swag2mcp.yaml                     # Archivo de configuración</span></span>
<span class="line"><span>├── cache/                            # Archivos de especificación remotos en caché</span></span>
<span class="line"><span>│   ├── a1b2c3d4e5f6...spec          # Contenido de especificación en caché</span></span>
<span class="line"><span>│   └── a1b2c3d4e5f6...meta          # Metadatos de la caché (JSON)</span></span>
<span class="line"><span>├── specs/                            # Archivos de especificación locales</span></span>
<span class="line"><span>│   └── my-api.yaml</span></span>
<span class="line"><span>├── responses/                        # Respuestas de API guardadas (respuestas grandes)</span></span>
<span class="line"><span>│   ├── meteo-get-forecast-abc123.json</span></span>
<span class="line"><span>│   └── response-fragment-def456.json</span></span>
<span class="line"><span>└── auth_scripts/                     # Scripts de autenticación</span></span>
<span class="line"><span>    ├── meteo.sh                      # Script de shell Unix</span></span>
<span class="line"><span>    └── meteo.bat                     # Script de batch Windows</span></span></code></pre></div><h2 id="ruta-predeterminada" tabindex="-1">Ruta Predeterminada <a class="header-anchor" href="#ruta-predeterminada" aria-label="Permalink to &quot;Ruta Predeterminada&quot;">​</a></h2><ul><li><strong>Linux/macOS</strong>: <code>~/.swag2mcp/</code></li><li><strong>Windows</strong>: <code>%USERPROFILE%\\.swag2mcp\\</code></li></ul><h2 id="ruta-personalizada" tabindex="-1">Ruta Personalizada <a class="header-anchor" href="#ruta-personalizada" aria-label="Permalink to &quot;Ruta Personalizada&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-workspace</span></span></code></pre></div><h2 id="directorios" tabindex="-1">Directorios <a class="header-anchor" href="#directorios" aria-label="Permalink to &quot;Directorios&quot;">​</a></h2><h3 id="cache" tabindex="-1">cache/ <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;cache/&quot;">​</a></h3><p>Almacena archivos de especificación remotos descargados. Cada archivo se almacena en caché con un hash SHA-256 de su URL como nombre de archivo:</p><ul><li><code>{hash}.spec</code> — el contenido del archivo de especificación en caché</li><li><code>{hash}.meta</code> — metadatos JSON (URL de origen, tiempo de caché, TTL)</li></ul><p>Cada archivo en caché tiene un TTL aleatorio entre 1 hora y 48 horas. La caché se verifica automáticamente en cada inicio — si existe una entrada válida (no expirada), se reutiliza sin descargar.</p><p><strong>Comandos:</strong></p><ul><li><code>swag2mcp update</code> — limpia la caché y vuelve a descargar todas las especificaciones</li><li><code>swag2mcp clean</code> — limpia la caché y las respuestas</li></ul><h3 id="specs" tabindex="-1">specs/ <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;specs/&quot;">​</a></h3><p>Almacena archivos de especificación locales a los que las colecciones apuntan mediante <code>location: specs/{name}</code>. Los archivos aquí se usan directamente sin almacenamiento en caché.</p><p>Este directorio se llena mediante:</p><ul><li><code>swag2mcp import &amp;lt;source&amp;gt; &amp;lt;name&amp;gt;</code> — descarga una especificación remota y la guarda aquí</li><li><code>swag2mcp export</code> — copia las especificaciones aquí en el ZIP de exportación</li><li>Colocación manual — puede copiar archivos de especificación aquí usted mismo</li></ul><h3 id="responses" tabindex="-1">responses/ <a class="header-anchor" href="#responses" aria-label="Permalink to &quot;responses/&quot;">​</a></h3><p>Almacena respuestas de API que exceden el límite de <code>max_response_size</code> (predeterminado 1 MB). Cuando el LLM invoca un endpoint y la respuesta es demasiado grande, swag2mcp la guarda aquí y devuelve una referencia de archivo en su lugar.</p><p>Convención de nomenclatura: <code>{domain}-{method}-{path_with_underscores}-{6char_hex}.json</code></p><p>Las respuestas antiguas se limpian automáticamente después de 48 horas al iniciar el servidor MCP.</p><h3 id="auth-scripts" tabindex="-1">auth_scripts/ <a class="header-anchor" href="#auth-scripts" aria-label="Permalink to &quot;auth_scripts/&quot;">​</a></h3><p>Almacena scripts de autenticación para el tipo de autenticación <code>script</code>. Cada script se nombra según el dominio de la especificación.</p><h4 id="convencion-de-nomenclatura" tabindex="-1">Convención de Nomenclatura <a class="header-anchor" href="#convencion-de-nomenclatura" aria-label="Permalink to &quot;Convención de Nomenclatura&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Plataforma</th><th>Nombre de archivo</th><th>Ejemplo</th></tr></thead><tbody><tr><td>Unix (Linux, macOS)</td><td><code>{domain}.sh</code></td><td><code>meteo.sh</code></td></tr><tr><td>Windows</td><td><code>{domain}.bat</code></td><td><code>meteo.bat</code></td></tr></tbody></table><p>El dominio no debe contener caracteres <code>/</code> o <code>\\</code>.</p><h4 id="como-funcionan-los-scripts" tabindex="-1">Cómo Funcionan los Scripts <a class="header-anchor" href="#como-funcionan-los-scripts" aria-label="Permalink to &quot;Cómo Funcionan los Scripts&quot;">​</a></h4><ol><li>swag2mcp ejecuta el script con un tiempo de espera de 30 segundos</li><li>El script debe generar JSON válido en stdout</li><li>swag2mcp analiza el JSON y usa el token para las solicitudes de API</li></ol><h4 id="formato-de-salida-esperado" tabindex="-1">Formato de Salida Esperado <a class="header-anchor" href="#formato-de-salida-esperado" aria-label="Permalink to &quot;Formato de Salida Esperado&quot;">​</a></h4><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;su-token-aquí&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Campo</th><th>Tipo</th><th>Requerido</th><th>Descripción</th></tr></thead><tbody><tr><td><code>token</code></td><td>string</td><td>✅</td><td>El token de autenticación</td></tr><tr><td><code>access_token</code></td><td>string</td><td>❌</td><td>Alternativa a <code>token</code> (se verifica primero)</td></tr><tr><td><code>token_type</code></td><td>string</td><td>❌</td><td>Tipo de token (por ejemplo, &quot;Bearer&quot;)</td></tr><tr><td><code>expires_in</code></td><td>number</td><td>❌</td><td>Vida útil del token en segundos (predeterminado: 3600)</td></tr></tbody></table><h4 id="ejecucion" tabindex="-1">Ejecución <a class="header-anchor" href="#ejecucion" aria-label="Permalink to &quot;Ejecución&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Plataforma</th><th>Comando</th></tr></thead><tbody><tr><td>Unix</td><td><code>sh {domain}.sh</code></td></tr><tr><td>Windows</td><td><code>cmd /c {domain}.bat</code></td></tr></tbody></table><h4 id="almacenamiento-en-cache-del-token" tabindex="-1">Almacenamiento en Caché del Token <a class="header-anchor" href="#almacenamiento-en-cache-del-token" aria-label="Permalink to &quot;Almacenamiento en Caché del Token&quot;">​</a></h4><p>El token se almacena en caché en memoria hasta que expira. En cada llamada a la API, swag2mcp verifica primero la caché — el script solo se ejecuta cuando el token en caché ha expirado.</p><h4 id="creacion-de-plantillas" tabindex="-1">Creación de Plantillas <a class="header-anchor" href="#creacion-de-plantillas" aria-label="Permalink to &quot;Creación de Plantillas&quot;">​</a></h4><p>Cuando configura <code>auth: { type: script, config: { domain: &quot;myapi&quot; } }</code>, swag2mcp crea un script de plantilla automáticamente:</p><p><strong>Unix (<code>auth_scripts/myapi.sh</code>):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;token&quot;: &quot;your-token-here&quot;, &quot;expires_in&quot;: 3600}&#39;</span></span></code></pre></div><p><strong>Windows (<code>auth_scripts/myapi.bat</code>):</strong></p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-token-here&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 3600}</span></span></code></pre></div><p>Reemplace el token de marcador de posición con su lógica de autenticación real.</p><h4 id="limpieza-de-huerfanos" tabindex="-1">Limpieza de Huérfanos <a class="header-anchor" href="#limpieza-de-huerfanos" aria-label="Permalink to &quot;Limpieza de Huérfanos&quot;">​</a></h4><p>Cuando elimina una especificación, su script de autenticación se vuelve huérfano. swag2mcp elimina automáticamente los scripts huérfanos en:</p><ul><li><code>swag2mcp update</code></li><li><code>swag2mcp clean</code></li></ul><h2 id="comandos" tabindex="-1">Comandos <a class="header-anchor" href="#comandos" aria-label="Permalink to &quot;Comandos&quot;">​</a></h2><h3 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Valida la configuración, limpia la caché y las respuestas, luego vuelve a descargar todos los archivos de especificación. También asegura que los scripts de autenticación existan y elimina los scripts huérfanos.</p><p>Use este comando después de:</p><ul><li>Agregar o eliminar colecciones</li><li>Cambiar las ubicaciones de las colecciones</li><li>Editar archivos de especificación que necesitan recarga en caché</li></ul><h3 id="clean" tabindex="-1">clean <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;clean&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Elimina todo el contenido de <code>cache/</code> y <code>responses/</code>, más los scripts de autenticación huérfanos. NO vuelve a almacenar en caché las especificaciones — use <code>update</code> para eso.</p><h3 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;validate&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Valida la configuración incluyendo todas las ubicaciones de colecciones. Consulte <a href="./../cli/validate">CLI: validate</a>.</p><h2 id="exportacion-e-importacion" tabindex="-1">Exportación e Importación <a class="header-anchor" href="#exportacion-e-importacion" aria-label="Permalink to &quot;Exportación e Importación&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportar espacio de trabajo a ZIP (nombre predeterminado: swag2mcp-backup-{date}.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportar a una ruta específica</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportar solo especificaciones específicas</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restaurar desde copia de seguridad</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span></code></pre></div><p>La exportación incluye: <code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>. La caché y las respuestas están excluidas (son datos locales).</p><h2 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h2><p>Si su espacio de trabajo está dentro de un repositorio Git, agregue estas entradas a <code>.gitignore</code>:</p><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># swag2mcp — solo datos locales</span></span>
<span class="line"><span>.swag2mcp/cache/</span></span>
<span class="line"><span>.swag2mcp/responses/</span></span></code></pre></div><p>Los directorios <code>cache/</code> y <code>responses/</code> contienen datos locales específicos de la máquina que no deben ser confirmados. Todo lo demás (<code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>) debe estar en el repositorio para que la configuración se comparta en todo el equipo.</p>`,66)])])}const k=e(t,[["render",o]]);export{u as __pageData,k as default};
